import{_ as o,a0 as s,w as a,s as p,I as e,x as t,a1 as r,A as n,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"何时使用 5G，何时使用 Wi-Fi 6 | LCTT x X-CMD","titleTemplate":false,"description":"何时使用 5G，何时使用 Wi-Fi 6 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"何时使用 5G，何时使用 Wi-Fi 6 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"何时使用 5G，何时使用 Wi-Fi 6 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20190612 When to use 5G, when to use Wi-Fi 6","title":"何时使用 5G，何时使用 Wi-Fi 6","tag":"202012","desc":""},"relativePath":"202012/20190612 When to use 5G, when to use Wi-Fi 6.md","filePath":"[post].md"}'),w={name:"202012/20190612 When to use 5G, when to use Wi-Fi 6.md"};function d(W,i,G,f,m,F){const l=s("Link");return a(),p("div",null,[i[28]||(i[28]=e("h1",{id:"何时使用-5g-何时使用-wi-fi-6",tabindex:"-1"},[t("何时使用 5G，何时使用 Wi-Fi 6 "),e("a",{class:"header-anchor",href:"#何时使用-5g-何时使用-wi-fi-6","aria-label":"Permalink to “何时使用 5G，何时使用 Wi-Fi 6”"},"​")],-1)),i[29]||(i[29]=e("blockquote",null,[e("p",null,"5G 是一种蜂窝服务, Wi-Fi 6 则是短程无线接入技术，这两种技术都有使其在特定企业角色中发挥作用的特性。")],-1)),i[30]||(i[30]=e("p",null,[e("img",{src:"https://images.idgesg.net/images/article/2017/07/wi-fi_wireless_communication_network_abstract_thinkstock_610127984_1200x800-100730107-large.jpg",alt:"Thinkstock"})],-1)),e("p",null,[i[2]||(i[2]=t("我们已经看到了关于 ",-1)),r(l,{href:"https://www.networkworld.com/article/3203489/what-is-5g-how-is-it-better-than-4g.html"},{default:n(()=>[...i[0]||(i[0]=[t("5G",-1)])]),_:1}),i[3]||(i[3]=t(" 蜂窝还是 ",-1)),r(l,{href:"https://www.networkworld.com/article/3215907/why-80211ax-is-the-next-big-thing-in-wi-fi.html"},{default:n(()=>[...i[1]||(i[1]=[t("Wi-Fi 6",-1)])]),_:1}),i[4]||(i[4]=t(" 将在企业使用中胜出的大肆宣传，但事实却是这两者在很大程度上互补，这将在 21 世纪 20 年代初形成一个有趣的竞争环境。",-1))]),i[31]||(i[31]=e("h3",{id:"_5g-在企业中的潜力",tabindex:"-1"},[t("5G 在企业中的潜力 "),e("a",{class:"header-anchor",href:"#_5g-在企业中的潜力","aria-label":"Permalink to “5G 在企业中的潜力”"},"​")],-1)),i[32]||(i[32]=e("p",null,"5G 对企业用户的承诺是在更低的延迟下提供更高的连接速度。蜂窝技术使用许可频段，可在很大程度上消除未经许可的 WiFi 频段可能会发生的潜在干涉。像当前的 4G LTE 技术一样，5G 可以由蜂窝无线运营商提供，也可以作为专用网络构建。",-1)),e("p",null,[i[6]||(i[6]=t("5G 的架构需要更多的无线接入点，并且在室内可能会出现连接质量较差或没有连接。因此，典型的组织需要为连接它的 PC、路由器和其他设备评估其 ",-1)),r(l,{href:"https://www.networkworld.com/article/3330603/5g-versus-4g-how-speed-latency-and-application-support-differ.html"},{default:n(()=>[...i[5]||(i[5]=[t("当前 4G 和潜在 5G 服务配置",-1)])]),_:1}),i[7]||(i[7]=t("。部署室内微蜂窝、中继器以及分布式天线可以帮助解决室内 5G 服务问题。与 4G 一样，5G 最佳的企业应用案例应该是用于真正的移动连接，例如，公共安全车和非地毯式覆盖区域（如采矿，石油与天然气开采、运输、农业和一些制造业）。",-1))]),i[33]||(i[33]=e("p",null,"除了广泛的移动性，5G 在漫游时的身份验证和部署速度方面也具有优势，这正好满足临时办公室或零售点的广域网连接需求。5G 将会拥有在视频直播这样的数据拥塞的情况下分流的能力。随着 5G 标准的成熟，该技术将提高其低功耗 IoT 连接的选择。",-1)),i[34]||(i[34]=e("p",null,"未来四到五年内，5G 将从大城市和特定地区开始逐步推出；4G 技术将在未来数年内继续流行。企业用户将需要新的设备、加密狗和路由器来连接 5G 服务。例如，苹果的 iPhone 预计要到 2020 年才能支持 5G，而物联网设备需要特定的蜂窝网络兼容性才能连接到 5G。（LCTT 译注：原文发表于 2019 年中）",-1)),i[35]||(i[35]=e("p",null,"Doyle Research 预计，5G 承诺的 1Gbps 和更高的带宽将对 SD-WAN 市场产生重大影响。4G LTE 已经使蜂窝服务成为主要的 WAN 连接。5G 可能比许多有线 WAN 选项（例如 MPLS 或互联网）更具成本竞争力或更便宜。5G 为企业 WAN 管理员提供了更多选择，为他们的分支站点和远程用户提供更多的带宽 —— 随着时间的推移，或将取代 MPLS。",-1)),i[36]||(i[36]=e("h3",{id:"wi-fi-6-在企业中的潜力",tabindex:"-1"},[t("Wi-Fi 6 在企业中的潜力 "),e("a",{class:"header-anchor",href:"#wi-fi-6-在企业中的潜力","aria-label":"Permalink to “Wi-Fi 6 在企业中的潜力”"},"​")],-1)),i[37]||(i[37]=e("p",null,"Wi-Fi 几乎无处不在，它可以将便携式笔记本电脑、平板电脑和其他设备连接到企业网络中。Wi-Fi 6（802.11ax）是 Wi-Fi 的最新版本，并有望提高速度、降低延迟、改善聚合带宽并提供高级流量管理。虽然 Wi-Fi 6 与 5G 有一些相似之处（两者均基于正交频分多址），但 Wi-Fi 6 不太容易受到干扰，能耗更低（延长设备电池的寿命），并提高了频谱效率。",-1)),e("p",null,[i[9]||(i[9]=t("与典型的 Wi-Fi 相同，目前许多厂商都有 ",-1)),r(l,{href:"https://www.networkworld.com/article/3309439/80211ax-preview-access-points-and-routers-that-support-the-wi-fi-6-protocol-on-tap.html"},{default:n(()=>[...i[8]||(i[8]=[t("Wi-Fi 6 早期厂商专用版本",-1)])]),_:1}),i[10]||(i[10]=t("。Wi-Fi 联盟计划在 2020 年获得 Wi-Fi 6 标准设备的认证。大多数企业将按照标准",-1)),i[11]||(i[11]=e("ruby",null,[t("接入点"),e("rt",null,"access-point")],-1)),i[12]||(i[12]=t("（AP）的生命周期（三年左右）升级到 Wi-Fi 6，除非他们有特定的性能/延迟要求，这将促使它们更快地升级。",-1))]),i[38]||(i[38]=u('<p>Wi-Fi 接入点仍然会受到干涉的影响。设计和配置接入点以提供适当的覆盖范围将会是一项挑战。企业 LAN 管理者将继续需要供应商提供的工具和合作伙伴来为组织配置最理想的 Wi-Fi 覆盖。Wi-Fi 6 解决方案必须与有线区域基础建设集成。Wi-Fi 供应商需要更好地为企业提供无线和有线解决方案的统一网络管理。</p><h3 id="有线回程的需求" tabindex="-1">有线回程的需求 <a class="header-anchor" href="#有线回程的需求" aria-label="Permalink to “有线回程的需求”">​</a></h3><p>对于这两种技术，通过无线与有线网络基础设施相结合，可以提供端到端的高速通信。在企业中，Wi-Fi 通常与区域和一些较大分支机构的有线以太网交换机搭配使用。一些设备通过电缆连接到交换机，其他设备则通过 Wi-Fi 连接，而笔记本电脑可能会同时采用这两种方法。Wi-Fi 接入点通过企业内部的以太网连接，并通过光纤连接连接到 WAN 或 Internet。</p><p>5G 的架构广泛使用光纤，将分布式无线接入网络连接回 5G 网络的核心。光纤通常需要提供将 5G 端点连接到基于 SaaS 的应用程序所需的高带宽，并提供实时视频和高速互联网访问。专用 5G 网络也必须满足高速有线连接要求。</p><h3 id="切换问题" tabindex="-1">切换问题 <a class="header-anchor" href="#切换问题" aria-label="Permalink to “切换问题”">​</a></h3><p>随着手机在 5G 和 Wi-Fi 6 之间切换，企业 IT 管理者要注意到切换挑战。这些问题会影响到性能和用户满意度。一些组织正在努力制定标准，以促进 Wi-Fi 6 和 5G 间更好的互操作性。 由于 Wi-Fi 6 的架构与 5G 接轨，在蜂窝网络与 Wi-Fi 网络间移动的体验应该更加顺滑。</p><h3 id="_5g-和-wi-fi-6-的对比取决于位置、应用和设备" tabindex="-1">5G 和 Wi-Fi 6 的对比取决于位置、应用和设备 <a class="header-anchor" href="#_5g-和-wi-fi-6-的对比取决于位置、应用和设备" aria-label="Permalink to “5G 和 Wi-Fi 6 的对比取决于位置、应用和设备”">​</a></h3><p>Wi-Fi 6 和 5G 在企业环境中的特定情况下相互竞争，这取决于位置、应用程序和设备类型。IT 管理者应该仔细评估他们当前和正在出现的连接性需求。Wi-Fi 将继续占领室内环境优势，而移动蜂窝网络将赢得更为广泛的室外覆盖。</p><p>一些重叠的情况发生在体育场馆、酒店和其他大型活动场所，许多用户将争夺带宽。政府应用（包括智能城市方面）可适用于 Wi-Fi 和蜂窝。医疗保健设施中有许多分布式医疗设备和需要连接的用户。大型分布式制造环境具有相似的特点。新兴的物联网应用环境可能是最有趣的“重叠使用案例”。</p><h3 id="对于-it-领导者的建议" tabindex="-1">对于 IT 领导者的建议 <a class="header-anchor" href="#对于-it-领导者的建议" aria-label="Permalink to “对于 IT 领导者的建议”">​</a></h3><p>虽然支持它们的无线技术正在融合，但 Wi-Fi 6 和 5G 从根本上来说是不同的网络，在企业连接中都有各自的作用。企业 IT 领导者应关注 Wi-Fi 和蜂窝网络如何相互补足，Wi-Fi 将继续作为内置技术，连接 PC 和笔记本电脑，处理手机和平板电脑数据，并实现一些物联网连接。</p><p>4G LTE 升级到 5G 后，仍将是手机和平板电脑连接的真正移动技术，也是 PC 连接的一种选择（通过加密狗），并在连接一些物联网设备方面越来越受欢迎。5G WAN 链路将日益成为标准，作为提高 SD-WAN 可靠性的备份和远程办公室的主要链路。</p><hr>',13)),e("p",null,[i[14]||(i[14]=t("via: ",-1)),r(l,{href:"https://www.networkworld.com/article/3402316/when-to-use-5g-when-to-use-wi-fi-6.html"},{default:n(()=>[...i[13]||(i[13]=[t("https://www.networkworld.com/article/3402316/when-to-use-5g-when-to-use-wi-fi-6.html",-1)])]),_:1})]),e("p",null,[i[19]||(i[19]=t("作者：",-1)),r(l,{href:"https://www.networkworld.com/author/Lee-Doyle/"},{default:n(()=>[...i[15]||(i[15]=[t("Lee Doyle",-1)])]),_:1}),i[20]||(i[20]=t(" 选题：",-1)),r(l,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[16]||(i[16]=[t("lujun9972",-1)])]),_:1}),i[21]||(i[21]=t(" 译者：",-1)),r(l,{href:"https://github.com/chenmu-kk"},{default:n(()=>[...i[17]||(i[17]=[t("chenmu-kk",-1)])]),_:1}),i[22]||(i[22]=t(" 校对：",-1)),r(l,{href:"https://github.com/wxy"},{default:n(()=>[...i[18]||(i[18]=[t("wxy",-1)])]),_:1})]),e("p",null,[i[25]||(i[25]=t("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[23]||(i[23]=[t("LCTT",-1)])]),_:1}),i[26]||(i[26]=t(" 原创编译，",-1)),r(l,{href:"https://linux.cn/"},{default:n(()=>[...i[24]||(i[24]=[t("Linux中国",-1)])]),_:1}),i[27]||(i[27]=t(" 荣誉推出",-1))])])}const x=o(w,[["render",d]]);export{k as __pageData,x as default};
